import React from "react";
import "bootstrap/dist/css/bootstrap.min.css";
import { useCart } from "../context/CartContext";

export default function Checkout() {
const { cartItems, setCartItems, removeFromCart } = useCart();

  const weightMultiplier = {
    "250g": 1,
    "500g": 2,
    "1kg": 4,
  };

  const handleQuantityChange = (id, value) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id
          ? { ...item, quantity: Math.max(1, value) }
          : item
      )
    );
  };

  const handleWeightChange = (id, weight) => {
    setCartItems(
      cartItems.map((item) =>
        item.id === id ? { ...item, weight } : item
      )
    );
  };

  const getItemTotal = (item) =>
    item.basePrice *
    weightMultiplier[item.weight] *
    item.quantity;

  const subtotal = cartItems.reduce(
    (sum, item) => sum + getItemTotal(item),
    0
  );

  const shipping = 50;
  const total = subtotal + shipping;

  if (cartItems.length === 0) {
    return (
      <div className="text-center py-5">
        <h4>Your cart is empty 🛒</h4>
      </div>
    );
  }

  return (
    <div className="py-5" style={{ background: "linear-gradient(135deg, #fdf6ec, #f7efe5)" }}>
      <div className="container">

        <div className="text-center mt-5">
          <h2 className="fw-bold text-brown">Checkout 🛒</h2>
          <p className="text-muted">Review your selected products</p>
        </div>

        <div className="row g-4">
          <div className="col-lg-8">
            <div className="card border-0 shadow-lg rounded-4">
              <div className="card-body p-4">

                {cartItems.map((item) => (
                  <div key={item.id} className="row align-items-center border-bottom py-3">

                    <div className="col-3 col-md-2">
                      <img src={item.image} alt={item.name} className="img-fluid rounded-3" />
                    </div>

                    <div className="col-9 col-md-4">
                      <h6>{item.name}</h6>
                      <small>Weight: {item.weight}</small>
                    </div>

                    <div className="col-md-2">
                      <select
                        className="form-select"
                        value={item.weight}
                        onChange={(e) => handleWeightChange(item.id, e.target.value)}
                      >
                        <option value="250g">250g</option>
                        <option value="500g">500g</option>
                        <option value="1kg">1kg</option>
                      </select>
                    </div>

                    <div className="col-md-2">
                      <input
                        type="number"
                        min="1"
                        className="form-control"
                        value={item.quantity}
                        onChange={(e) => handleQuantityChange(item.id, e.target.value)}
                      />
                    </div>

                    <div className="col-md-2 text-end">
  <strong>₹{getItemTotal(item)}</strong>
  <button
  className="btn btn-sm btn-outline-danger mt-2"
  onClick={() => removeFromCart(item.id, item.weight)}
>
  Remove
</button>

</div>

                  </div>
                ))}

              </div>
            </div>
          </div>

          <div className="col-lg-4">
            <div className="card shadow-lg rounded-4">
              <div className="card-body">
                <h5>Price Summary</h5>
                <p>Subtotal: ₹{subtotal}</p>
                <p>Shipping: ₹{shipping}</p>
                <h5>Total: ₹{total}</h5>
              </div>
            </div>
          </div>

        </div>
      </div>
    </div>
  );
}
